diff --git a/lib/evmcow/execution_state.hpp b/lib/evmcow/execution_state.hpp
index b185c93..45df179 100644
--- a/lib/evmcow/execution_state.hpp
+++ b/lib/evmcow/execution_state.hpp
@@ -8,7 +8,11 @@
 #include <string>
 #include <vector>
 #include <optional>
-#include <array>
+#include <algorithm>
+#include <atomic>
+#include <mutex>
+#include <bit>
+#include <memory>

 namespace evmcow
 {
@@ -40,42 +44,676 @@ public:
     alignas(sizeof(uint256)) uint256 m_stack_space[limit];
 };

-/// Checkpoint-capable stack. This correctness-first fallback stores every frame eagerly.
+/// Snapshots share an immutable baseline. Slots exposed for mutation have a
+/// stable ordinal, so a snapshot only needs a dense image of those slots.
 class StackTop
 {
+    struct History;
+    struct View
+    {
+        History* history;
+        const uint256* external{};
+        uint32_t changes{}, packed{}, offset{};
+    };
+    struct History
+    {
+        struct ViewBlock
+        {
+            static constexpr size_t capacity = 32;
+            View records[capacity];
+            std::unique_ptr<ViewBlock> next;
+        };
+        View base_view{this};
+        std::unique_ptr<ViewBlock> views;
+        size_t used_views{};
+        View* make_view(size_t n, size_t p, uint32_t offset, const uint256* external)
+        {
+            if (!n && !p) return &base_view;
+            if (!views || used_views == ViewBlock::capacity)
+            {
+                auto block = std::make_unique<ViewBlock>();
+                block->next = std::move(views);
+                views = std::move(block);
+                used_views = 0;
+            }
+            auto* view = &views->records[used_views++];
+            *view = {this, external, static_cast<uint32_t>(n), static_cast<uint32_t>(p), offset};
+            return view;
+        }
+        struct Block
+        {
+            std::unique_ptr<uint256[]> words;
+            std::unique_ptr<Block> next;
+            explicit Block(size_t n) : words{new uint256[n]} {}
+        };
+        std::atomic<size_t> refs{1};
+        unsigned credits{};
+        size_t width, room, used;
+        size_t pack_begin{}, pack_limit{};
+        std::unique_ptr<uint256[]> owned;
+        uint256* words;
+        std::unique_ptr<uint256[]> owned_arena;
+        uint256* arena;
+        bool borrowed{};
+        std::unique_ptr<std::atomic<uint32_t>[]> rank;
+        mutable std::mutex mutex;
+        std::unique_ptr<Block> blocks;
+        size_t block_used{}, block_size{}, heap_used{};
+
+        History(uint256* active, size_t extent, size_t n)
+          : width{n}, room{extent - n}, used{0}, owned{new uint256[n]}, words{owned.get()},
+            arena{active + n}, borrowed{room != 0}, rank{new std::atomic<uint32_t>[n]{}}
+        {}
+        explicit History(size_t n)
+          : width{n}, room{0}, used{0}, owned{new uint256[n]}, words{owned.get()}, arena{words} {}
+        void detach()
+        {
+            std::lock_guard lock{mutex};
+            owned_arena.reset(new uint256[used]);
+            std::copy_n(arena, used, owned_arena.get());
+            arena = owned_arena.get();
+            room = used;
+            borrowed = false;
+        }
+        uint256* allocate_image(size_t n, uint32_t& offset, const uint256*& external)
+        {
+            if (n <= room - used)
+            {
+                offset = static_cast<uint32_t>(used);
+                used += n;
+                return arena + offset;
+            }
+            if (n > block_size - block_used)
+            {
+                const auto size = std::max(n, width / 4);
+                auto b = std::make_unique<Block>(size);
+                b->next = std::move(blocks);
+                blocks = std::move(b);
+                block_used = 0;
+                block_size = size;
+                heap_used += size;
+            }
+            auto* w = blocks->words.get() + block_used;
+            block_used += n;
+            external = w;
+            return w;
+        }
+        const uint256& word(size_t i, size_t count, size_t packed, const uint256* image) const
+        {
+            if (count || packed)
+            {
+                const auto j = rank[i].load(std::memory_order_relaxed) - 1;
+                if (i >= pack_begin && i < pack_limit)
+                {
+                    if (j < packed) return image[j];
+                }
+                else if (j < count) return image[packed + j];
+            }
+            return words[i];
+        }
+        void retain() { refs.fetch_add(1, std::memory_order_relaxed); }
+        void release(size_t n = 1)
+        {
+            if (refs.fetch_sub(n, std::memory_order_acq_rel) == n) delete this;
+        }
+        void ticket()
+        {
+            if (!credits)
+            {
+                constexpr unsigned batch = 32;
+                refs.fetch_add(batch, std::memory_order_relaxed);
+                credits = batch;
+            }
+            --credits;
+        }
+    };
+    class Handle
+    {
+        History* ptr{};
+    public:
+        Handle() = default;
+        explicit Handle(History* p) : ptr{p} {}
+        Handle(const Handle& other) : ptr{other.ptr} { if (ptr) ptr->retain(); }
+        Handle(Handle&& other) noexcept : ptr{std::exchange(other.ptr, nullptr)} {}
+        Handle& operator=(Handle other) noexcept
+        {
+            std::swap(ptr, other.ptr);
+            return *this;
+        }
+        void reset()
+        {
+            if (ptr) ptr->release();
+            ptr = nullptr;
+        }
+        void set(History* other)
+        {
+            if (other == ptr) return;
+            if (other) other->retain();
+            reset();
+            ptr = other;
+        }
+        ~Handle() { reset(); }
+        explicit operator bool() const { return ptr != nullptr; }
+        History* get() const { return ptr; }
+        History* operator->() const { return ptr; }
+        History& operator*() const { return *ptr; }
+    };
+
+    static constexpr uint32_t slice_flag = uint32_t{1} << 31;
+    struct Slices
+    {
+        uint256* base;
+        std::atomic<uint32_t> refs;
+        std::vector<uint256> backing;
+        mutable std::mutex mutex;
+        Slices(uint256* p, uint32_t refs) : base{p}, refs{refs} {}
